input.content:
#include <clocale>
#include <cstdio>
#include <fmt/format.h>

int main() {
  auto loc = std::locale(std::locale("en_US.UTF-8"));
  auto check = [&](const char* fmtstr, auto v) {
    auto s = fmt::format(loc, fmtstr, v);
    printf("[%s] len=%zu\n", s.c_str(), s.size());
  };
  check("{:12.3Lf}", 0.295L);      // last branch
  check("{:12.3Lf}", 0.001234L);   // leading zeros
  check("{:12.3Lf}", 1234.5678L);  // grouping
  check("{:12.3Lf}", 1.295L);
  check("{:12.3Lf}", -5.980L);
  check("{:12L}", 1234567.0L);
  check("{:12}", 1234567.0);       // non-localized
  check("{:12.3f}", 0.295);
  check("{:12.5e}", 12345.678);    // exp format
  check("{:12.10f}", 0.000123456789012L);
  check("{:#12.0f}", 1234.5L);
  check("{:12.3Lf}", 0.0L);
  return 0;
}

